const runClaimStep: StepRunner = (_customer, state, step) => {
  const damages = step.incident?.damages ?? [];
  const insuredItems = insuredItemsFor(state, step);

  const payout = sumOf(
    damages.map((damage) => damagePayout(insuredItems, damage)),
  );
  const cap = policyCap(insuredItems);

  return appendResult(state, { payout, remainingCap: cap - payout });
};
